1331	// ---------------------------------------------------------------------------
1332	// 业务校验
1333	// ---------------------------------------------------------------------------
1334	
1335	function formatResourceIds(store: Store, ids: string[]): string {
1336	  return ids
1337	    .map((id) => {
1338	      const r = store.resources.find((x) => x.id === id);
1339	      return r ? `${id}（${r.name}）` : id;
1340	    })
1341	    .join('、');
1342	}
1343	
1344	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
1345	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
1346	  const problems: string[] = [];
1347	  const seen = new Set<string>();
1348	  const dupes: string[] = [];
1349	  for (const id of rawIds) {
1350	    if (seen.has(id)) {
1351	      if (!dupes.includes(id)) dupes.push(id);
1352	    }
1353	    seen.add(id);
1354	  }
1355	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
1356	
1357	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
1358	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
1359	
1360	  if (problems.length > 0) throw new BizError(problems.join('\n'));
1361	  return [...seen].sort();
1362	}
1363	
1364	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
1365	  return mergeIntervals(
1366	    r.open.map(
1367	      ([s, e]) =>
1368	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
1369	    ),
1370	  );
1371	}
1372	
1373	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1374	function subtractSegments(
1375	  segments: Array<[number, number]>,
1376	  cuts: Array<[number, number]>,
1377	): Array<[number, number]> {
1378	  let result = segments;
1379	  for (const [cs, ce] of mergeIntervals(cuts)) {
1380	    const next: Array<[number, number]> = [];
1381	    for (const [s, e] of result) {
1382	      if (ce <= s || e <= cs) {
1383	        next.push([s, e]);
1384	        continue;
1385	      }
1386	      if (s < cs) next.push([s, cs]);
1387	      if (ce < e) next.push([ce, e]);
1388	    }
1389	    result = next;
1390	  }
1391	  return result;
1392	}
1393	
1394	// 某资源的有效停用记录（按开始时间、标识排序）
1395	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
1396	  return store.closures
1397	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
1398	    .sort(
1399	      (a, b) =>
1400	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
1401	        a.id.localeCompare(b.id),
1402	    );
1403	}
1404	
1405	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
1406	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
1407	  const cuts = activeClosuresOf(store, r.id).map(
1408	    (c) =>
1409	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
1410	  );
1411	  return subtractSegments(openSegmentsOf(r), cuts);
1412	}
1413	
1414	interface CoverageGap {
1415	  id: string;
1416	  r: ResourceRec;
1417	  closures: ClosureRec[]; // 与该区间重叠的相关有效停用（按开始时间、标识排序）
1418	}
1419	
1420	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
1421	function findCoverageGaps(
1422	  store: Store,
1423	  ids: string[],
1424	  startMin: number,
1425	  endMin: number,
1426	): CoverageGap[] {
1427	  const gaps: CoverageGap[] = [];
1428	  for (const id of ids) {
1429	    const r = store.resources.find((x) => x.id === id)!;
1430	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
1431	    const closures = activeClosuresOf(store, id).filter((c) => {
1432	      const cs = parseDateTime(c.start, '停用开始时间');
1433	      const ce = parseDateTime(c.end, '停用结束时间');
1434	      return cs < endMin && startMin < ce;
1435	    });
1436	    gaps.push({id, r, closures});
1437	  }
1438	  return gaps;
1439	}
1440	
1441	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
1442	function gapLines(gaps: CoverageGap[], indent: string): string[] {
1443	  const lines: string[] = [];
1444	  for (const g of gaps) {
1445	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
1446	    for (const c of g.closures) {
1447	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
1448	    }
1449	  }
1450	  return lines;
1451	}
1452	
1453	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
1454	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
1455	  const failing = findCoverageGaps(store, ids, startMin, endMin);
1456	  if (failing.length > 0) {
1457	    throw new BizError(
1458	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
1459	        gapLines(failing, '').join('\n'),
1460	    );
1461	  }
1462	}
1463	
1464	interface Conflict {
1465	  booking: BookingRec;
1466	  shared: string[];
1467	}
1468	
1469	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1470	function findConflicts(
1471	  store: Store,
1472	  ids: string[],
1473	  startMin: number,
1474	  endMin: number,
1475	  excludeBookingId?: string,
1476	): Conflict[] {
1477	  const wanted = new Set(ids);
1478	  const conflicts: Conflict[] = [];
1479	  for (const b of store.bookings) {
1480	    if (b.status !== 'active') continue;
1481	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1482	    const bStart = parseDateTime(b.start, '预约开始时间');
1483	    const bEnd = parseDateTime(b.end, '预约结束时间');
1484	    const overlap = bStart < endMin && startMin < bEnd;
1485	    if (!overlap) continue;
1486	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1487	    if (shared.length > 0) conflicts.push({booking: b, shared});
1488	  }
1489	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1490	  return conflicts;
1491	}
1492	
1493	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1494	  if (conflicts.length === 0) return;
1495	  const lines = conflicts.map(
1496	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1497	  );
1498	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1499	}
1500	
1501	// ---------------------------------------------------------------------------
1502	// 多项预约目标的统一批次校验（无写入副作用）
1503	//
1504	// 创建系列、批量改期、安全撤销与 iCalendar 导入共用本套逻辑，不再各自重复
1505	// 整批可行性循环。校验针对“全部目标生效后”的安排，统一三类检查：
1506	//   1) 实际可用覆盖：开放区间重叠或相接合并后扣除有效停用并集，须连续覆盖目标；
1507	//   2) 批外占用：批外有效预约（已取消不占用）与目标的共同资源时间重叠；
1508	//   3) 批内冲突：本批各目标彼此之间的共同资源时间重叠。
1509	// 区间一律左闭右开，端点相接可行；仅共同资源重叠才算冲突。
1510	// 本函数只读取数据与目标，绝不修改目标、业务记录或标识计数；
1511	// 全部失败项一次性收集（批内冲突在双方各自的失败项中都出现），
1512	// 诊断的业务定位（成员时间/预约标识/UID）与报告顺序由各入口负责。
1513	// ---------------------------------------------------------------------------
1514	
1515	interface ValidationTarget {
1516	  startMin: number;
1517	  endMin: number;
1518	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1519	}
1520	
1521	interface BatchTargetFailure {
1522	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1523	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1524	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1525	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1526	}
1527	
1528	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1529	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1530	function validateBatchTargets(
1531	  store: Store,
1532	  targets: ReadonlyArray<ValidationTarget>,
1533	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
1534	): BatchTargetFailure[] {
1535	  const failures: BatchTargetFailure[] = [];
1536	  for (let i = 0; i < targets.length; i++) {
1537	    const t = targets[i];
1538	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1539	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1540	      (c) => !excludeBookingIds.has(c.booking.id),
1541	    );
1542	    const wanted = new Set(t.resourceIds);
1543	    const internal: BatchTargetFailure['internal'] = [];
1544	    for (let j = 0; j < targets.length; j++) {
1545	      if (j === i) continue;
1546	      const o = targets[j];
1547	      if (!(o.startMin < t.endMin && t.startMin < o.endMin)) continue;
1548	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1549	      if (shared.length > 0) internal.push({otherIndex: j, shared});
1550	    }
1551	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1552	      failures.push({index: i, gaps, external, internal});
1553	    }
1554	  }
1555	  return failures;
1556	}
1557	
1558	// ---------------------------------------------------------------------------
1559	// 命令行解析
1560	// ---------------------------------------------------------------------------
1561	
1562	interface GlobalArgs {
1563	  dataFile: string;
1564	  help: boolean;
1565	  rest: string[];
1566	}
1567	
1568	function splitGlobalArgs(argv: string[]): GlobalArgs {
1569	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1570	  for (let i = 0; i < argv.length; i++) {
1571	    const a = argv[i];
1572	    if (a === '-h' || a === '--help') {
1573	      result.help = true;
1574	    } else if (a === '--data') {
1575	      const v = argv[++i];
1576	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1577	      result.dataFile = v;
1578	    } else if (a.startsWith('--data=')) {
1579	      result.dataFile = a.slice('--data='.length);
1580	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1581	    } else {
1582	      result.rest.push(a);
1583	    }
1584	  }
1585	  return result;
1586	}
1587	
1588	interface ParsedFlags {
1589	  values: Map<string, string[]>;
1590	  positionals: string[];
1591	}
1592	
1593	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1594	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1595	  const allowedSet = new Set(allowed);
1596	  const multiSet = new Set(multi);
1597	  const values = new Map<string, string[]>();
1598	  const positionals: string[] = [];
1599	
1600	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1601	    if (inline !== undefined) return [inline, index];
1602	    const v = args[index + 1];
1603	    if (v === undefined || v.startsWith('-')) {
1604	      throw new UsageError(`选项 --${key} 缺少值`);
1605	    }
1606	    return [v, index + 1];
1607	  };
1608	
1609	  for (let i = 0; i < args.length; i++) {
1610	    const a = args[i];
1611	    if (a.startsWith('--')) {
1612	      let key: string;
1613	      let inline: string | undefined;
1614	      const eq = a.indexOf('=');
1615	      if (eq >= 0) {
1616	        key = a.slice(2, eq);
1617	        inline = a.slice(eq + 1);
1618	      } else {
1619	        key = a.slice(2);
1620	      }
1621	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1622	      let v: string;
1623	      [v, i] = takeValue(key, inline, i);
1624	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1625	      if (!multiSet.has(key) && values.has(key)) {
1626	        throw new UsageError(`选项 --${key} 只能指定一次`);
1627	      }
1628	      const list = values.get(key) ?? [];
1629	      list.push(v);
1630	      values.set(key, list);
1631	    } else if (a.startsWith('-') && a !== '-') {
1632	      throw new UsageError(`未知参数: ${a}`);
1633	    } else {
1634	      positionals.push(a);
1635	    }
1636	  }
1637	  return {values, positionals};
1638	}
1639	
1640	function requireFlag(values: Map<string, string[]>, key: string): string {
1641	  const v = values.get(key)?.[0];
1642	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1643	  return v;
1644	}
