199	  const manifest = writeManifest(dir, 'multi.json', [
200	    {bookingId: 'B0003', start: '2026-10-12T14:00', end: '2026-10-12T15:00', resourceIds: ['R0001']},
201	    {bookingId: 'B0001', start: '2026-10-12T21:00', end: '2026-10-12T22:00', resourceIds: ['R0001']},
202	    {bookingId: 'B0002', start: '2026-10-12T14:30', end: '2026-10-12T15:30', resourceIds: ['R0001']},
203	  ]);
204	  const bytesBefore = readFileSync(df);
205	  const r = bizFail(df, ['reschedule-batch', manifest], '多项失败');
206	  assert.match(r.stderr, /共 3 项不满足条件（按清单顺序）/);
207	  const i1 = r.stderr.indexOf('第 1 项 B0003');
208	  const i2 = r.stderr.indexOf('第 2 项 B0001');
209	  const i3 = r.stderr.indexOf('第 3 项 B0002');
210	  assert.ok(i1 >= 0 && i2 > i1 && i3 > i2, '失败项按清单顺序而非标识顺序报告');
211	  assert.match(r.stderr, /第 1 项 B0003[\s\S]*?B0004（2026-10-12T14:00 → 2026-10-12T15:00）/, '批外冲突');
212	  assert.match(r.stderr, /第 2 项 B0001[\s\S]*?开放不足资源:[\s\S]*?R0001/, '开放不足');
213	  assert.match(
214	    r.stderr,
215	    /第 3 项 B0002[\s\S]*?B0003（本批第 1 项目标 2026-10-12T14:00 → 2026-10-12T15:00）/,
216	    '批内冲突列对方标识与目标时间',
217	  );
218	  assertFileBytes(df, bytesBefore, '多项失败逐字节保留');
219	  const store = readStore(df);
220	  assertArrangement(store, 'B0003', '2026-10-12T11:00', '2026-10-12T12:00', ['R0001'], '整批不变');
221	  assert.equal(store.batchOps.length, 0, '不留操作记录');
222	  assert.equal(store.batchSeq, 0, '操作计数不变');
223	});
224	
225	// ---------------------------------------------------------------------------
226	// 3. 停用造成的覆盖不足（系列入口）：列出不足资源与相关有效停用标识和时间
227	// ---------------------------------------------------------------------------
228	
229	test('创建系列：有效停用造成覆盖不足，解除后整批成功', (t) => {
230	  const dir = tempDir(t);
231	  const df = join(dir, 'data.json');
232	  addResource(df, '甲'); // R0001
233	  ok(
234	    df,
235	    ['add-closure', '--resource', 'R0001', '--start', '2026-10-19T00:00', '--end', '2026-10-20T00:00'],
236	    '有效停用 C0001',
237	  );
238	
239	  // 第 2 项成员（2026-10-19）落入停用区间：整批失败，列出相关停用标识与时间
240	  const args = [
241	    'create-series', '--resource', 'R0001',
242	    '--start', '2026-10-12T10:00', '--end', '2026-10-12T11:00', '--count', '3',
243	  ];
244	  const bytesBefore = readFileSync(df);
245	  const r = bizFail(df, args, '停用造成覆盖不足');
246	  assert.match(r.stderr, /系列创建失败：共 1 项不满足条件（按发生顺序）/);
247	  assert.match(r.stderr, /第 2 项 2026-10-19T10:00 → 2026-10-19T11:00/);
248	  assert.match(r.stderr, /开放不足资源:[\s\S]*?R0001/);
249	  assert.match(r.stderr, /相关有效停用: C0001（2026-10-19T00:00 → 2026-10-20T00:00）/);
250	  assertFileBytes(df, bytesBefore, '系列失败逐字节保留');
251	  let store = readStore(df);
252	  assert.equal(store.bookings.length, 0, '不创建任何成员');
253	  assert.equal(store.series.length, 0, '不创建系列');
254	  assert.equal(store.bookingSeq, 0, '预约计数不变');
255	  assert.equal(store.seriesSeq, 0, '系列计数不变');
256	  const seriesView = ok(df, ['list-series'], '新进程系列查询');
257	  assert.match(seriesView.stdout, /暂无预约系列/);
258	
259	  // 解除停用后同一请求整批成功，标识从 S0001/B0001 起分配（未被失败尝试消费）
260	  ok(df, ['cancel-closure', 'C0001'], '解除停用');
261	  const r2 = ok(df, args, '解除后创建系列');
262	  assert.match(r2.stdout, /已创建按周重复系列 S0001/);
263	  assert.match(r2.stdout, /第 2 项 B0002: 2026-10-19T10:00 → 2026-10-19T11:00/);
264	  store = readStore(df);
265	  assert.equal(store.bookings.length, 3);
266	  assert.equal(store.seriesSeq, 1);
267	  const seriesView2 = ok(df, ['list-series'], '新进程确认系列成员');
268	  assert.match(seriesView2.stdout, /B0002 \[有效\] 2026-10-19T10:00 → 2026-10-19T11:00/);
269	});
270	
271	// ---------------------------------------------------------------------------
272	// 4. 改期/取消后的重放预约占用：重放项按当前安排与状态参与既有占用，
273	//    不用首次导入快照代替现状
274	// ---------------------------------------------------------------------------
275	
276	test('导入：重放预约改期后按新安排占用、取消后不再占用', (t) => {
277	  const dir = tempDir(t);
278	  const df = join(dir, 'data.json');
279	  addResource(df, '甲'); // R0001
280	
281	  const f1 = writeIcal(dir, 'a.ics', ical(event('uid-a', '20261012T100000', '20261012T110000')));
282	  ok(df, ['import-ical', f1, '--resource', 'R0001'], '首次导入 uid-a（B0001）');
283	  ok(
284	    df,
285	    ['reschedule-booking', 'B0001', '--start', '2026-10-12T15:00', '--end', '2026-10-12T16:00'],
286	    '改期重放源预约',
287	  );
288	
289	  // 重放 uid-a（首次导入快照为 10:00-11:00）+ 新项 uid-b 10:00-11:00：
290	  // B0001 当前已改到 15:00-16:00，原时段不再占用，新项可行
291	  const f2 = writeIcal(dir, 'b.ics', ical(
292	    event('uid-a', '20261012T100000', '20261012T110000'),
293	    event('uid-b', '20261012T100000', '20261012T110000'),
294	  ));
295	  const r1 = ok(df, ['import-ical', f2, '--resource', 'R0001'], '改期后重放+新项');
296	  assert.match(r1.stdout, /新增 1 项，重放 1 项/);
297	  assert.match(r1.stdout, /uid-a[\s\S]*?当前安排: 2026-10-12T15:00 → 2026-10-12T16:00/);
298	  let store = readStore(df);
299	  assertArrangement(store, 'B0002', '2026-10-12T10:00', '2026-10-12T11:00', ['R0001'], '新项占用原时段');
300	
301	  // 新项 uid-c 15:30-16:30 与 B0001 的当前安排（而非首次导入快照）冲突：整批拒绝
302	  const f3 = writeIcal(dir, 'c.ics', ical(
303	    event('uid-a', '20261012T100000', '20261012T110000'),
304	    event('uid-c', '20261012T153000', '20261012T163000'),
305	  ));
306	  const bytesBefore = readFileSync(df);
307	  const r2 = bizFail(df, ['import-ical', f3, '--resource', 'R0001'], '与改期后安排冲突');
308	  assert.match(r2.stderr, /uid-c[\s\S]*?B0001（2026-10-12T15:00 → 2026-10-12T16:00）/, '按当前安排参与占用');
309	  assertFileBytes(df, bytesBefore, '冲突整批未导入');
310	  assert.equal(readStore(df).bookings.length, 2);
311	
312	  // 取消 B0001 后：重放报告已取消且不复活；同一 uid-c 不再受阻（取消不占用）
313	  ok(df, ['cancel-booking', 'B0001'], '取消重放源预约');
314	  const r3 = ok(df, ['import-ical', f3, '--resource', 'R0001'], '取消后重放+新项');
315	  assert.match(r3.stdout, /uid-a[\s\S]*?当前状态: 已取消/);
316	  assert.match(r3.stdout, /uid-c[\s\S]*?新预约 B0003/);
317	  store = readStore(df);
318	  assert.equal(bookingOf(store, 'B0001').status, 'cancelled', '重放不复活已取消预约');
319	  assertArrangement(store, 'B0003', '2026-10-12T15:30', '2026-10-12T16:30', ['R0001'], '取消后新项可行');
320	  const dayView = ok(df, ['list-bookings', '--date', '2026-10-12'], '新进程按日查询');
321	  assert.match(dayView.stdout, /B0001 \[已取消\] 2026-10-12T15:00 → 2026-10-12T16:00/);
322	  assert.match(dayView.stdout, /B0003 \[已预约\] 2026-10-12T15:30 → 2026-10-12T16:30/);
323	});
324	
325	// ---------------------------------------------------------------------------
326	// 5. 保存失败与无变化操作的文件保护
327	// ---------------------------------------------------------------------------
328	
329	test('文件保护：保存失败逐字节保留且不消费标识；无变化操作不写文件', (t) => {
330	  const dir = tempDir(t);
331	  const df = join(dir, 'data.json');
332	  addResource(df, '甲'); // R0001
333	  createBooking(df, ['R0001'], '2026-10-12T09:00', '2026-10-12T10:00', 'B0001');
334	
335	  // (a) 无变化批量改期：成功但不写文件、不建记录、不推进计数
336	  const noop = writeManifest(dir, 'noop.json', [
337	    {bookingId: 'B0001', start: '2026-10-12T09:00', end: '2026-10-12T10:00', resourceIds: ['R0001']},
338	  ]);
339	  const bytesBefore = readFileSync(df);
340	  const mtimeBefore = statSync(df).mtimeMs;
341	  const r1 = ok(df, ['reschedule-batch', noop], '无变化批量改期');
342	  assert.match(r1.stdout, /无业务变化/);
343	  assertFileBytes(df, bytesBefore, '无变化提交不写文件');
344	  assert.equal(statSync(df).mtimeMs, mtimeBefore, '修改时间不变');
345	  let store = readStore(df);
346	  assert.equal(store.batchOps.length, 0);
347	  assert.equal(store.batchSeq, 0);
348	
349	  // (b) 全重放导入：成功但不写文件、不推进计数
350	  const f = writeIcal(dir, 'a.ics', ical(event('uid-x', '20261012T160000', '20261012T170000')));
351	  ok(df, ['import-ical', f, '--resource', 'R0001'], '首次导入 uid-x（B0002）');
352	  const bytesAfterImport = readFileSync(df);
353	  const r2 = ok(df, ['import-ical', f, '--resource', 'R0001'], '全重放导入');
354	  assert.match(r2.stdout, /全部为重放/);
355	  assertFileBytes(df, bytesAfterImport, '全重放不写文件');
356	  store = readStore(df);
357	  assert.equal(store.bookingSeq, 2, '预约计数不变');
358	  assert.equal(store.imports.length, 1, '不新增导入身份');
359	
360	  // (c) 保存失败：同一原数据放到保存必然失败的位置（文件名 255 字节）
361	  const change = writeManifest(dir, 'change.json', [
362	    {bookingId: 'B0001', start: '2026-10-12T14:00', end: '2026-10-12T15:00', resourceIds: ['R0001']},
363	  ]);
364	  const origBytes = readFileSync(df);
365	  const longFile = join(dir, LONG_NAME);
366	  writeFileSync(longFile, origBytes);
367	  const r3 = bizFail(longFile, ['reschedule-batch', change], '保存失败批量改期');
368	  assert.ok(!r3.stdout.includes('成功'), '不报告成功');
369	  assert.ok(!r3.stdout.includes('O0001'), '不报告操作标识');
370	  assertFileBytes(longFile, origBytes, '保存失败逐字节保留');
371	  store = readStore(longFile);
372	  assertArrangement(store, 'B0001', '2026-10-12T09:00', '2026-10-12T10:00', ['R0001'], '没有部分改期');
373	  assert.equal(store.batchOps.length, 0, '不留操作记录');
374	  assert.equal(store.batchSeq, 0, '标识未消费');
375	
376	  // (d) 同一原数据在可保存位置重试：成功且操作标识未被失败尝试消费
377	  const retryFile = join(dir, 'retry.json');
378	  writeFileSync(retryFile, origBytes);
379	  const r4 = ok(retryFile, ['reschedule-batch', change], '可保存位置重试');
380	  assert.match(r4.stdout, /O0001/, '标识未被消费，仍为 O0001');
381	  store = readStore(retryFile);
382	  assertArrangement(store, 'B0001', '2026-10-12T14:00', '2026-10-12T15:00', ['R0001'], '重试生效');
383	  assert.equal(store.batchSeq, 1);
384	  const opsView = ok(retryFile, ['list-batch-ops'], '新进程查询操作记录');
385	  assert.match(opsView.stdout, /O0001 \[未撤销\]/);
386	});
