async function cmdFindSlot(args: string[]): Promise<void> {
  const {values, positionals} = parseFlags(args, ['window', 'duration', 'group'], ['group']);
  if (positionals.length > 0) throw new UsageError(`find-slot 不接受位置参数: ${positionals.join(' ')}`);

