    const ids = raw.split(',');
    if (ids.some((id) => id === '')) {
      throw new BizError(`第 ${i + 1} 个需求组含有空的资源标识: “${raw}”，应为逗号分隔的候选资源标识`);
    }
    const dupes = ids.filter((id, j) => ids.indexOf(id) !== j);
    if (dupes.length > 0) {
      throw new BizError(`第 ${i + 1} 个需求组内资源重复指定: ${[...new Set(dupes)].join('、')}`);
    }
    const unknown = ids.filter((id) => !store.resources.some((r) => r.id === id));
    if (unknown.length > 0) {
      throw new BizError(`第 ${i + 1} 个需求组含未知资源标识: ${[...new Set(unknown)].sort().join('、')}`);
    }
    // 组内候选按标识排序：输入顺序不影响结果（同一起点取字典序最小序列）
    return [...ids].sort(compareIds);
  });
